import{_ as o,o as l,c as a,a2 as i}from"./chunks/framework.CWWEQfK7.js";const h=JSON.parse('{"title":"开始并跟踪第一次分析","description":"启动完整项目分析，理解运行状态，并在刷新页面后继续跟踪结果。","frontmatter":{"page_id":"guide-follow-a-run","description":"启动完整项目分析，理解运行状态，并在刷新页面后继续跟踪结果。"},"headers":[],"relativePath":"guide/follow-a-run.md","filePath":"guide/follow-a-run.md","lastUpdated":1786290726000}'),r={name:"guide/follow-a-run.md"};function d(c,e,t,n,p,s){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="开始并跟踪第一次分析" tabindex="-1">开始并跟踪第一次分析 <a class="header-anchor" href="#开始并跟踪第一次分析" aria-label="Permalink to &quot;开始并跟踪第一次分析&quot;">​</a></h1><p>Ershu 的仓库分析是后台长任务。API 创建运行，Worker 从队列取出任务，前端负责显示当前快照和后续事件。本页说明怎样判断运行真的在推进，以及结束后应检查什么。</p><h2 id="开始前检查" tabindex="-1">开始前检查 <a class="header-anchor" href="#开始前检查" aria-label="Permalink to &quot;开始前检查&quot;">​</a></h2><p>第一次运行前应满足：</p><ul><li>项目至少有一个活动仓库；</li><li>已启用可用的大语言模型（LLM）通道；</li><li>API 和 Worker 使用同一套数据库配置；</li><li>Worker 进程正在运行；</li><li>私有远程仓库已经配置可用凭据。</li></ul><p>如果 Worker 没有运行，API 仍可能成功创建任务，但状态会停留在队列中。</p><h2 id="第-1-步-使用完整项目范围" tabindex="-1">第 1 步：使用完整项目范围 <a class="header-anchor" href="#第-1-步-使用完整项目范围" aria-label="Permalink to &quot;第 1 步：使用完整项目范围&quot;">​</a></h2><p>进入项目的 <strong>运行</strong> 页面，选择 <strong>新建运行</strong>。</p><p>第一次运行选择：</p><ul><li>类型：<strong>完整项目</strong>（<code>full_project</code>）；</li><li>仓库范围：<strong>全部活动仓库</strong>；</li><li>分支：留空使用各仓库默认分支，或填写你确定存在的分支；</li><li>LLM 通道：使用项目默认值或选择另一个已启用通道；</li><li>embedding 通道：需要语义索引时选择已启用的独立通道；</li><li>并行：不确定时保持关闭，此时仓库按并行数 <code>1</code> 处理。</li></ul><p>在基线尚未建立时，后端只允许完整项目运行，并要求覆盖全部活动仓库。前端会显示基线提示并锁定仓库范围。</p><p>选择 <strong>新建运行</strong> 后，新记录会出现在列表顶部。看到 <code>queued</code>、<code>running</code>、<code>scanning</code>、<code>analyzing</code> 或 <code>finalizing</code> 中的任一状态，说明运行仍是活动状态。</p><h2 id="第-2-步-确认-worker-正在推进任务" tabindex="-1">第 2 步：确认 Worker 正在推进任务 <a class="header-anchor" href="#第-2-步-确认-worker-正在推进任务" aria-label="Permalink to &quot;第 2 步：确认 Worker 正在推进任务&quot;">​</a></h2><p>运行列表在存在活动任务时每隔约 5 秒刷新。打开运行详情，可以看到已经持久化的快照、时间线、分析块、工具调用和用量信息；具体内容取决于任务当前阶段。</p><p>如果状态长时间停在 <code>queued</code>：</p><ol><li>检查 Worker 终端是否仍在运行。</li><li>确认 Worker 和 API 读取同一份数据库及相关密钥配置。</li><li>查看 Worker 的当前错误，而不是反复创建新运行。</li></ol><p>成功的中间结果是状态从 <code>queued</code> 继续进入扫描、分析或收尾阶段，详情页也开始出现新的时间线内容。</p><h2 id="第-3-步-安全刷新页面" tabindex="-1">第 3 步：安全刷新页面 <a class="header-anchor" href="#第-3-步-安全刷新页面" aria-label="Permalink to &quot;第 3 步：安全刷新页面&quot;">​</a></h2><p>活动运行首次打开时，前端读取当前快照，再从快照游标之后接收事件。你可以刷新浏览器或稍后重新打开同一个运行，不需要从最早的输出重新播放。</p><p>刷新成功后，你应看到：</p><ul><li>同一个运行编号；</li><li>已经保存的分析内容；</li><li>从当前游标继续出现的新事件，而不是重新创建一个任务。</li></ul><p>不要把浏览器事件流当作任务本身。关闭页面不会取消 Worker 中的运行。</p><h2 id="第-4-步-判断是否完成" tabindex="-1">第 4 步：判断是否完成 <a class="header-anchor" href="#第-4-步-判断是否完成" aria-label="Permalink to &quot;第 4 步：判断是否完成&quot;">​</a></h2><p>终止状态包括：</p><ul><li><code>completed</code>：运行完成；</li><li><code>completed_with_warnings</code>：运行完成，但有需要检查的警告；</li><li><code>failed</code>：运行失败；</li><li><code>cancelled</code>：运行已取消。</li></ul><p>完成或带警告完成后，前端直接读取最终结果，不再保持事件流连接。详情页应能显示最终过程文本、分析块、用量、警告和本次生成的文档。</p><p>完成后请核对：</p><ol><li>运行状态是 <code>completed</code> 或 <code>completed_with_warnings</code>。</li><li>详情页显示最终结果，而不是持续等待新事件。</li><li>生成文档区域至少列出本次实际产出的文档。</li><li>搜索索引状态符合预期；如果是 <code>degraded</code> 或 <code>unavailable</code>，先阅读警告，不要把它描述成完整语义索引。</li></ol><p><code>completed_with_warnings</code> 不是无条件成功。可以继续使用已经生成的结果，但应先确认哪些仓库、文档或索引没有完整生成。</p><h2 id="取消和重试" tabindex="-1">取消和重试 <a class="header-anchor" href="#取消和重试" aria-label="Permalink to &quot;取消和重试&quot;">​</a></h2><p>有项目管理权限的用户可以取消活动运行。取消请求完成后，状态会变为 <code>cancelled</code>；页面关闭本身不会取消任务。</p><p>终止状态的运行可以通过页面的重试操作创建新运行。重试后会出现新的运行记录，请跟踪新记录，不要等待旧记录恢复为活动状态。</p><p>当文档已经生成后，继续<a href="./read-search-chat">阅读文档、搜索项目和发起问答</a>。</p>',33)])])}const _=o(r,[["render",d]]);export{h as __pageData,_ as default};
